exit 14 0 SV-01 from_SV04
mark from_SV01 14 3 S
mark vault 14 16 N
door 14 13 locked lock=100 kind=steel "비축 창고"

prop w_plaque_wall 3 1
text 3 3 "명패 벽. 손톱만 한 놋쇠 명패가 빽빽하다 — '제1차 당선 오버시어'부터 '제750차'까지. 맨 끝 한 칸은 빈 틀." w=3 scene=SQS13_PLAQUE
prop overseer_desk 13 6
term 14 6 TM-SV04
prop chair_n 14 7
text 22 4 "오버시어실 창. 아트리움이 내려다보인다. 기표소 다섯이 한 줄." w=2
prop bookshelf 24 9
text 24 9 "회차별 선거 공보철. 2096년 공보 한 장만 빨간 줄 — '배급 연동 폐지'." w=2
text 14 11 "비축 창고 문. 전자 자물쇠에 '당선 오버시어 열쇠'. 손잡이에 140년 먼지." scene=SQS13_VAULT

# 비축 창고(문이 열린 뒤)
prop crate_army 5 16
prop crate_army 8 16
prop crate_metal 18 16
prop tube_rack 22 15
text 5 16 "비축 상자. 2077년 선거 공탁금 금고 · 진공관 · 세진 회로 기판 · 볼트 점프슈트(S-02)." w=4 scene=SQS13_CRATE cond="SQ_S13_LOOT == 0"
text 5 16 "비축 상자. 몫을 나누고 남은 자리 — 상자 바닥에 명부 사본이 깔렸다." w=4 cond="SQ_S13_LOOT >= 1"

# 당선 오버시어 금고(재미 검수 반영 — 주인공 당선이면 빈 채로 열린다 · 비우고 '삼으면' 내 보관 자리(털림 판정은 월드 L-R02-04 자리 · 위협 1))
prop safe_big 24 16 cond="SQ_S13_WIN == 1 and SQ_S13_LOOT >= 1"
box 24 16 safe lock=50 name="당선 오버시어 금고" claim=799,1104 th=1 cond="SQ_S13_WIN == 1 and SQ_S13_LOOT >= 1"
